INSERT INTO training_exercises (category,name,summary,description,benefits,target,difficulty,cues,mistakes,level_min,sort_order,image_url)
VALUES
($sd$콤비네이션$sd$,$sd$상하 믹스 6연타 콤비$sd$,$sd$머리와 몸을 번갈아 치는 여섯 번 연속 공격을 배워요.$sd$,$sd$블루 리그에서 익힌 콤비를 여섯 번 연타로 확장하는 훈련입니다. 예시 콤비는 1-2-3(머리)-2(바디)-3(바디)-2(머리)처럼 위와 아래를 번갈아 공격하며 리듬을 유지합니다. 한 타 한 타 정확한 폼을 지키면서 마지막까지 가드가 내려가지 않는 것이 핵심입니다. 속도보다 연결의 부드러움을 먼저 완성해 주세요.$sd$,$sd$$sd$,$sd$$sd$,$sd$중급$sd$,$sd$["치기 전에 위-아래-위 목표를 머릿속에 먼저 그린다", "바디를 칠 때는 무릎을 굽혀 눈높이째 내려간다", "여섯 타 내내 반대 손은 턱 옆에 붙인다", "마지막 타 후 스텝 백까지가 한 세트"]$sd$::jsonb,$sd$["뒤로 갈수록 팔로만 휘두른다 → 매 타마다 발과 허리 회전을 싣는다", "바디샷에서 허리만 숙인다 → 무릎을 굽혀 몸 전체를 낮춘다", "속도 욕심에 타격이 뭉개진다 → 정확한 폼이 먼저, 속도는 그다음"]$sd$::jsonb,21,210,$sd$/assets/training/mixed-level-six-punch-combo.png$sd$),
($sd$콤비네이션$sd$,$sd$바디샷 콤비 입문$sd$,$sd$잽으로 위를 보게 한 다음 몸통을 치는 방법을 배워요.$sd$,$sd$머리 공격으로 상대 시선을 위로 끌어올린 뒤 몸통을 공격하는 기본 바디 콤비 훈련입니다. 잽-바디 스트레이트, 원투-리드 바디훅 두 가지 패턴을 반복합니다. 바디를 칠 때는 무릎을 굽혀 자세 전체를 낮추고, 친 뒤에는 재빨리 가드와 스탠스를 회복합니다. 샌드백이나 미트에 대고 낮은 타깃을 정확히 맞히는 감각을 익혀 주세요.$sd$,$sd$$sd$,$sd$$sd$,$sd$중급$sd$,$sd$["잽으로 상대 시선을 위로 끌어올린다", "바디 타격 순간 무릎을 굽혀 어깨가 타깃 높이로 내려간다", "친 뒤에는 곧바로 가드와 스탠스를 회복한다"]$sd$::jsonb,$sd$["팔만 뻗어 아래를 친다 → 다리로 낮아진 뒤 몸통 회전으로 친다", "바디를 친 후 그 자리에 머문다 → 즉시 일어나며 가드 복귀"]$sd$::jsonb,21,211,$sd$/assets/training/body-shot-combination.png$sd$),
($sd$쿨다운$sd$,$sd$레드 쿨다운 루틴$sd$,$sd$훈련 뒤에 몸을 천천히 식히고 어깨와 허리를 풀어요.$sd$,$sd$강도 높은 레드 리그 훈련 후 심박수를 서서히 낮추는 마무리 루틴입니다. 제자리 걷기 1분으로 호흡을 고른 뒤, 어깨 돌리기·가슴 펴기·허리 비틀기 스트레칭을 각 20초씩 진행합니다. 마지막으로 손목과 목을 천천히 풀며 오늘의 라운드를 돌아봅니다. 반동을 쓰지 않고 부드럽게 늘리는 것이 포인트입니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$중급$sd$,$sd$["반동 없이 천천히 20초씩 늘린다", "호흡은 코로 들이쉬고 입으로 길게 내쉰다", "오늘 라운드에서 잘된 것 하나를 떠올리며 마무리한다"]$sd$::jsonb,$sd$["훈련이 끝나자마자 바로 주저앉는다 → 1분 걷기로 심박을 서서히 낮춘다", "아픈 범위까지 당긴다 → 시원한 정도에서 멈춘다"]$sd$::jsonb,21,212,$sd$/assets/training/red-league-cooldown-routine.png$sd$),
($sd$카운터$sd$,$sd$슬립 카운터$sd$,$sd$상대 주먹을 살짝 피하면서 동시에 되받아쳐요.$sd$,$sd$블루 리그에서 배운 슬립에 반격을 연결하는 카운터 훈련입니다. 코치가 미트로 잽을 던지면 바깥쪽으로 슬립한 뒤 곧바로 스트레이트로 되받아칩니다. 피하는 동작과 치는 동작이 하나처럼 이어지는 것이 목표입니다. 시선은 끝까지 미트를 향해 유지해 주세요.$sd$,$sd$$sd$,$sd$$sd$,$sd$중급$sd$,$sd$["슬립은 주먹이 스칠 만큼만 작게", "피하는 발과 치는 손이 거의 동시에 움직인다", "시선은 끝까지 상대(미트)에 고정", "카운터 후 스탠스와 가드를 리셋"]$sd$::jsonb,$sd$["슬립이 너무 크다 → 머리를 한 뼘만 옮긴다", "피하고 한 박자 쉰 뒤 친다 → 회피와 반격을 한 동작처럼 잇는다"]$sd$::jsonb,22,223,$sd$/assets/training/slip-counter-punch.png$sd$),
($sd$카운터$sd$,$sd$패리 카운터$sd$,$sd$날아오는 주먹을 손바닥으로 빗겨내고 바로 반격해요.$sd$,$sd$상대의 잽을 손바닥으로 살짝 빗겨낸 뒤 즉시 되받아치는 카운터 훈련입니다. 패리는 크게 쳐내는 것이 아니라 궤도를 10센티미터만 바꾸는 작은 동작입니다. 빗겨내는 순간 이미 반격이 출발해야 상대가 돌아올 틈이 없습니다. 코치의 미트 잽에 맞춰 패리-원투 리듬을 반복해 주세요.$sd$,$sd$$sd$,$sd$$sd$,$sd$중급$sd$,$sd$["패리는 쳐내기가 아니라 살짝 빗겨내기", "빗겨내는 즉시 반격이 함께 출발한다", "패리하는 손 반대편 가드는 그대로 유지"]$sd$::jsonb,$sd$["크게 휘둘러 쳐낸다 → 손목 스냅으로 10cm만 빗겨낸다", "패리에 정신이 팔려 반격을 잊는다 → 빗겨내면 바로 친다를 한 세트로 외운다"]$sd$::jsonb,22,224,$sd$/assets/training/parry-counter-punch.png$sd$),
($sd$풋워크$sd$,$sd$피벗 아웃 앵글 어택$sd$,$sd$몸을 돌려 옆으로 빠진 다음 새 각도에서 공격해요.$sd$,$sd$정면 싸움에서 벗어나 옆 각도를 만드는 실전 풋워크 훈련입니다. 원투를 친 뒤 앞발을 축으로 몸을 회전해 상대의 측면으로 빠져나갑니다. 새 각도가 만들어지면 지체 없이 원투나 리드훅으로 이어서 공격합니다. 회전하는 동안에도 가드와 시선은 항상 상대를 향해야 합니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$중급$sd$,$sd$["원투 후 앞발을 축으로 몸을 회전한다", "회전 중에도 가드와 시선은 상대에게", "새 각도에 서자마자 지체 없이 공격으로 잇는다"]$sd$::jsonb,$sd$["피벗할 때 두 발이 함께 뜬다 → 앞발은 바닥에 붙이고 뒷발만 돌린다", "각도만 만들고 멈춘다 → 각도는 공격을 위한 것, 바로 콤비로 잇는다"]$sd$::jsonb,23,235,$sd$/assets/training/pivot-out-angle-attack.png$sd$),
($sd$방어$sd$,$sd$클린치 기초·안전 이탈$sd$,$sd$너무 가까워졌을 때 안전하게 정리하고 빠져나와요.$sd$,$sd$거리가 무너져 상대와 몸이 붙었을 때 안전하게 상황을 정리하는 기술입니다. 파트너와 서로 치지 않는 약속 아래, 팔을 안쪽으로 감아 상대 팔을 컨트롤하는 자세를 연습합니다. 코치의 신호에 맞춰 옆으로 스텝하며 밀지 않고 부드럽게 빠져나옵니다. 이탈 직후 가드를 올리고 거리를 회복하는 것까지가 한 세트입니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$중급$sd$,$sd$["머리는 세우고 이마는 상대 어깨 근처에 둔다", "팔은 상대 팔 안쪽으로 감아 컨트롤한다", "빠질 때는 옆으로 스텝하며 가드부터 올린다", "코치 신호 전까지 힘겨루기 금지"]$sd$::jsonb,$sd$["힘으로 밀어낸다 → 각도를 만들어 옆으로 부드럽게 빠진다", "고개를 숙여 시야를 잃는다 → 머리를 세우고 상대를 본다"]$sd$::jsonb,23,236,$sd$/assets/training/clinch-basics-safe-exit.png$sd$),
($sd$콤비네이션$sd$,$sd$위빙 연결 콤비$sd$,$sd$U자로 피한 힘을 그대로 훅에 실어서 쳐요.$sd$,$sd$블루 리그에서 배운 위빙을 공격과 하나로 잇는 콤비 훈련입니다. 리드훅을 친 뒤 U자를 그리며 반대편으로 위빙하고, 올라오는 힘을 그대로 리어훅에 싣습니다. 무릎으로 내려갔다가 일어나는 하체의 힘이 펀치로 이어지는 감각을 익힙니다. 훅-위빙-훅 패턴이 익숙해지면 원투-위빙-리어훅으로 확장해 주세요.$sd$,$sd$$sd$,$sd$$sd$,$sd$중급$sd$,$sd$["리드훅 후 U자를 그리며 반대편으로 이동", "위빙은 허리가 아니라 무릎으로 내려간다", "올라오는 힘을 그대로 리어훅에 싣는다"]$sd$::jsonb,$sd$["위빙 후 자세가 무너진 채 친다 → 스탠스를 회복한 뒤 힘을 싣는다", "고개를 숙여 바닥을 본다 → 시선은 전방, 턱은 당긴다"]$sd$::jsonb,24,247,$sd$/assets/training/weave-into-combo.png$sd$),
($sd$스파링준비$sd$,$sd$시나리오 섀도복싱$sd$,$sd$눈앞에 상대가 있다고 상상하며 상황극처럼 연습해요.$sd$,$sd$눈앞에 가상의 상대를 세워 두고 상황을 정해 움직이는 전술 훈련입니다. 예를 들어 상대가 잽을 던진다고 상상하면 슬립 후 카운터로, 상대가 다가온다면 피벗으로 각도를 바꿉니다. 코치가 라운드마다 시나리오를 하나씩 정해 주며, 혼자 하지만 실제 공방처럼 거리와 타이밍을 그립니다. 몸에 익힌 기술을 상황과 연결하는 다리 역할을 하는 훈련입니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$중급$sd$,$sd$["라운드마다 시나리오 하나에만 집중한다", "가상 상대의 키와 거리까지 구체적으로 상상한다", "기술과 기술 사이에 바운스와 가드를 유지한다"]$sd$::jsonb,$sd$["그냥 콤비 반복이 된다 → 상대가 이렇게 하면 나는 이렇게를 정해 두고 움직인다", "허공만 보고 친다 → 상대의 눈 위치를 정해 두고 시선을 고정한다"]$sd$::jsonb,24,248,$sd$/assets/training/scenario-shadow-boxing.png$sd$),
($sd$샌드백$sd$,$sd$샌드백 파워 인터벌$sd$,$sd$정해진 시간 동안 힘차게 치고 잠깐 쉬기를 반복해요.$sd$,$sd$샌드백에 체중을 온전히 싣는 인터벌 훈련입니다. 20초 동안 원투와 훅에 힘을 실어 치고, 40초는 가벼운 잽과 스텝으로 회복합니다. 한 라운드에 이 사이클을 3회 반복하며, 힘을 실을 때도 폼이 무너지지 않는 것이 핵심입니다. 손목이 꺾이지 않도록 정타로 맞히는 데 집중해 주세요.$sd$,$sd$$sd$,$sd$$sd$,$sd$고급$sd$,$sd$["힘을 실을수록 손목을 곧게, 정타로 맞힌다", "파워 구간에도 반대 손은 턱 옆 가드", "회복 구간에는 잽과 스텝으로 호흡을 정리한다"]$sd$::jsonb,$sd$["지치면 샌드백에 기댄다 → 거리를 지키고 스텝으로 버틴다", "어깨 힘만으로 친다 → 발끝-허리-어깨 순서로 힘을 전달한다"]$sd$::jsonb,24,249,$sd$/assets/training/heavy-bag-power-interval.png$sd$),
($sd$미트$sd$,$sd$미트 리액션 드릴$sd$,$sd$코치가 부르는 콜을 듣자마자 바로 그 콤비를 쳐요.$sd$,$sd$코치의 콜과 미트 위치를 보고 즉시 반응하는 훈련입니다. 정해진 순서 없이 코치가 원투, 쓰리-투, 바디처럼 콜을 섞어 부르면 지체 없이 해당 콤비를 칩니다. 생각하는 시간을 줄이고 눈과 몸이 먼저 반응하게 만드는 것이 목표입니다. 콜과 콜 사이에는 바운스와 가드를 유지하며 다음 신호를 기다립니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$중급$sd$,$sd$["콜을 들으면 반 박자 안에 첫 타가 출발한다", "콜 사이에는 바운스와 가드를 유지한다", "헷갈리는 콜이 나와도 멈추지 말고 잽으로 연결한다"]$sd$::jsonb,$sd$["콜을 예상하고 미리 움직인다 → 신호가 나온 뒤에 반응하는 것이 훈련이다", "빨리 치려다 폼이 무너진다 → 반응 속도는 정확한 폼 위에서만 인정된다"]$sd$::jsonb,25,260,$sd$/assets/training/mitt-reaction-drill.png$sd$),
($sd$풋워크$sd$,$sd$미러 풋워크 드릴$sd$,$sd$파트너와 마주 보고 거울처럼 발만 따라 움직여요.$sd$,$sd$파트너와 일정한 거리를 두고 마주 서서, 리더의 움직임을 거울처럼 따라가는 훈련입니다. 서로 주먹은 전혀 내지 않으며 전진·후진·사이드 스텝으로만 거리를 유지합니다. 상대의 어깨와 발을 보며 움직임을 미리 읽는 눈을 기릅니다. 역할을 바꿔 가며 리더와 팔로어를 모두 경험해 주세요.$sd$,$sd$$sd$,$sd$$sd$,$sd$중급$sd$,$sd$["상대의 가슴과 앞발을 함께 본다", "거리는 두 팔 길이로 늘 일정하게", "스텝은 미끄러지듯, 점프 금지"]$sd$::jsonb,$sd$["발만 보고 따라간다 → 어깨 움직임에서 다음 스텝을 예측한다", "가까워지면 손이 나간다 → 이 훈련은 노 펀치, 발로만 말한다"]$sd$::jsonb,25,261,$sd$/assets/training/mirror-footwork-drill.png$sd$),
($sd$미트$sd$,$sd$미트 디펜스 리액션$sd$,$sd$코치의 미트 공격을 보고 피하거나 막은 뒤 되받아요.$sd$,$sd$코치가 미트로 천천히 잽과 훅의 궤적을 그려 주면, 슬립·위빙·블록 중 알맞은 방어로 반응하는 훈련입니다. 미트를 사용하기 때문에 안전하게 실전 감각을 기를 수 있습니다. 방어 직후에는 반드시 가벼운 원투로 되받아 카운터 습관을 만듭니다. 속도는 코치가 단계적으로 올리며, 무리한 속도는 사용하지 않습니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$중급$sd$,$sd$["미트의 궤적을 끝까지 보고 방어를 고른다", "직선 공격은 슬립·패리, 곡선 공격은 위빙·블록", "방어 직후 가벼운 원투로 되받는다"]$sd$::jsonb,$sd$["눈을 감거나 고개를 돌린다 → 턱을 당기고 끝까지 본다", "방어만 하고 끝낸다 → 방어와 반격은 한 세트"]$sd$::jsonb,25,262,$sd$/assets/training/mitt-defense-reaction.png$sd$),
($sd$스파링준비$sd$,$sd$터치 스파링 입문(잽 게임)$sd$,$sd$보호장비를 쓰고 아주 가볍게 잽만 주고받아요.$sd$,$sd$처음으로 상대와 가볍게 주고받는 터치 스파링 입문 훈련입니다. 헤드기어·마우스피스·16온스 글러브 등 보호장비를 모두 착용하고, 반드시 코치 감독 아래에서만 진행합니다. 파워는 20% 이하의 터치 수준으로, 잽만 사용해 거리와 타이밍을 느끼는 것이 목표입니다. 시작 전 스파링 동의서 확인이 필요하며, 세게 치기 경쟁이 아니라 컨트롤을 배우는 시간입니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$고급$sd$,$sd$["파워는 20% — 닿기만 하면 성공", "잽 외의 펀치는 사용하지 않는다", "맞아도 흥분하지 않고 호흡을 유지한다", "코치의 스톱 콜에 즉시 멈춘다"]$sd$::jsonb,$sd$["점점 세게 친다 → 코치 신호에 맞춰 즉시 파워를 다시 낮춘다", "이기려는 마음에 돌진한다 → 거리 유지가 이 훈련의 점수다"]$sd$::jsonb,26,273,$sd$/assets/training/touch-sparring-jab-game.png$sd$),
($sd$스파링준비$sd$,$sd$디펜스 온리 터치 스파링$sd$,$sd$치지 않고 피하고 막기만 하는 안 맞기 게임이에요.$sd$,$sd$한 명은 가벼운 터치 공격만, 다른 한 명은 방어만 맡는 역할 스파링입니다. 헤드기어·마우스피스·16온스 글러브 등 보호장비를 착용하고 코치 감독 아래 파워 20% 이하로 진행합니다. 방어자는 슬립·위빙·블록·스텝으로 최대한 맞지 않는 것이 목표이며 반격은 하지 않습니다. 라운드마다 역할을 바꾸며 맞지 않는 자신감을 쌓는 훈련입니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$고급$sd$,$sd$["보호장비 확인 후 코치 신호로만 시작한다", "슬립·위빙·블록·스텝을 골고루 사용한다", "맞아도 당황하지 말고 가드부터 회복한다", "공격 역할도 파워 20% 터치를 유지한다"]$sd$::jsonb,$sd$["구석으로 계속 밀린다 → 사이드 스텝으로 중앙을 되찾는다", "눈을 감고 버틴다 → 시선을 유지해야 다음 공격이 보인다"]$sd$::jsonb,27,284,$sd$/assets/training/defense-only-touch-sparring.png$sd$),
($sd$샌드백$sd$,$sd$바디샷 샌드백 라운드$sd$,$sd$샌드백 아래쪽을 몸통이라 생각하고 집중해서 쳐요.$sd$,$sd$샌드백의 아랫부분을 상대의 몸통이라 생각하고 바디샷을 집중 연습하는 라운드입니다. 무릎을 굽혀 자세를 낮춘 뒤 바디 스트레이트와 바디훅을 섞어 콤비로 연결합니다. 낮아졌다가 다시 일어나며 머리 공격으로 잇는 상하 연계도 함께 훈련합니다. 낮은 자세를 오래 유지해야 하므로 하체 힘도 자연스럽게 길러집니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$중급$sd$,$sd$["무릎을 굽혀 타깃 높이까지 내려간다", "바디훅은 팔꿈치 각도를 유지한 채 몸통 회전으로 친다", "아래를 친 뒤 일어나며 머리 공격으로 연결한다"]$sd$::jsonb,$sd$["허리를 접어 숙인 채 친다 → 무릎으로 낮아져 균형을 지킨다", "바디샷마다 가드가 내려간다 → 반대 손은 항상 턱 옆에"]$sd$::jsonb,27,285,$sd$/assets/training/heavy-bag-body-shot-round.png$sd$),
($sd$스파링준비$sd$,$sd$공수 전환 터치 스파링$sd$,$sd$신호에 맞춰 공격 역할과 방어 역할을 서로 바꿔요.$sd$,$sd$코치의 신호에 따라 공격과 방어 역할이 바뀌는 터치 스파링입니다. 보호장비 전체 착용, 코치 감독, 파워 20% 이하 터치 규칙은 동일하게 지킵니다. 공격 30초, 방어 30초처럼 구간을 나누어 들어가기와 빠지기를 모두 경험합니다. 역할이 바뀌는 순간의 거리 조절과 마음 전환이 이 훈련의 핵심입니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$고급$sd$,$sd$["신호가 바뀌면 1초 안에 역할을 전환한다", "공격 구간에도 파워는 20% 터치", "빠질 때는 뒤가 아니라 옆 각도로 이동한다"]$sd$::jsonb,$sd$["공격 구간에 흥분해 파워가 올라간다 → 코치 콜에 맞춰 즉시 낮춘다", "방어로 바뀐 뒤에도 계속 친다 → 신호 소리에 몸이 먼저 반응하게 연습한다"]$sd$::jsonb,28,296,$sd$/assets/training/attack-defense-switch-sparring.png$sd$),
($sd$컨디셔닝$sd$,$sd$라운드 서바이벌 인터벌$sd$,$sd$3분 라운드 동안 쉬지 않고 움직이는 체력 훈련이에요.$sd$,$sd$실전 라운드를 끝까지 버티는 체력을 만드는 인터벌 훈련입니다. 3분 라운드 안에서 펀치아웃 20초, 스쿼트 10회, 가벼운 스텝 30초를 순서대로 반복합니다. 라운드 사이 휴식은 1분이며, 휴식 중에도 완전히 멈추지 않고 걸으며 호흡을 고릅니다. 힘든 순간에도 자세가 무너지지 않는 습관을 기르는 것이 목표입니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$고급$sd$,$sd$["힘들수록 자세를 먼저 점검한다", "치면서 짧게 내쉬는 호흡 리듬을 유지한다", "휴식 1분에도 완전히 멈추지 않고 걷는다"]$sd$::jsonb,$sd$["후반에 가드가 내려간다 → 지칠 때의 가드가 진짜 실력이다", "숨을 참고 몰아친다 → 타격마다 짧게 내쉰다"]$sd$::jsonb,29,307,$sd$/assets/training/round-survival-interval.png$sd$),
($sd$스파링준비$sd$,$sd$레드 통합 리허설$sd$,$sd$레드에서 배운 기술을 한 흐름으로 이어서 점검해요.$sd$,$sd$타이틀매치를 앞두고 레드 리그의 기술을 하나의 흐름으로 점검하는 리허설입니다. 시나리오 섀도 1라운드, 미트 리액션 1라운드, 코치 감독 아래 터치 스파링 1라운드를 이어서 진행합니다. 스파링 구간은 보호장비 전체 착용과 파워 20% 터치 규칙을 그대로 지킵니다. 라운드가 끝나면 잘된 점과 보완할 점을 코치와 함께 기록하며 마무리합니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$고급$sd$,$sd$["세 라운드를 하나의 시험처럼 이어서 진행한다", "스파링 구간은 보호장비·파워 20% 규칙 그대로", "라운드마다 코치 피드백을 한 가지씩 기록한다"]$sd$::jsonb,$sd$["잘 보이려고 파워를 올린다 → 심사는 컨트롤을 본다", "실수하면 멈춰 버린다 → 흐름을 유지하고 다음 동작으로 잇는다"]$sd$::jsonb,30,318,$sd$/assets/training/red-league-integration-rehearsal.png$sd$),
($sd$스파링준비$sd$,$sd$페이스 컨트롤 라운드 운영$sd$,$sd$3분 라운드를 내 계획대로 강약을 나눠 운영하는 훈련이에요.$sd$,$sd$라운드를 처음부터 끝까지 같은 힘으로 몰아치면 마지막에 힘이 빠집니다. 이 훈련에서는 3분을 1분씩 세 구간(탐색-압박-마무리)으로 나누고, 구간마다 출력을 다르게 배분하며 섀도 또는 샌드백 라운드를 운영합니다. 타이머 신호에 맞춰 강도를 스스로 올리고 내리는 감각을 익히면, 어떤 라운드에서도 흔들리지 않는 운영 능력이 생깁니다. 블랙 리그의 첫 관문인 '내 페이스로 움직이기'를 몸에 새기는 훈련입니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$고급$sd$,$sd$["1분마다 기어를 바꾸듯 출력 전환", "탐색 구간은 잽과 스텝 위주로 가볍게", "압박 구간에도 호흡은 일정하게", "마지막 30초는 계획한 콤비로 마무리"]$sd$::jsonb,$sd$["처음부터 전력으로 몰아침 → 첫 1분은 60% 출력으로 관찰과 탐색에 사용", "구간이 바뀌어도 리듬이 그대로 → 타이머 신호마다 스텝 템포부터 바꾸기"]$sd$::jsonb,31,310,$sd$/assets/training/pace-control-round.png$sd$),
($sd$스파링준비$sd$,$sd$상대 유형별 게임플랜 섀도$sd$,$sd$상대 유형을 정해 놓고 맞춤 작전으로 라운드를 뛰는 전략 훈련이에요.$sd$,$sd$블랙 리그에서는 '무엇을 칠까'보다 '어떻게 풀어갈까'를 먼저 생각합니다. 훈련 전에 상대 유형(계속 들어오는 유형, 멀리서 도는 유형, 받아치는 유형) 중 하나를 골라 대응 작전을 세 줄로 적고, 그 작전대로 라운드를 운영합니다. 라운드가 끝나면 작전대로 움직였는지 스스로 점검하고 한 가지를 수정해 다시 뜁니다. 생각하고, 실행하고, 되돌아보는 이 순환이 코치의 눈을 만들어 줍니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$고급$sd$,$sd$["시작 전 작전 3줄을 소리 내어 말하기", "들어오는 상대에겐 사이드로 비켜 각 만들기", "도는 상대에겐 앞으로 반 발씩 거리 좁히기", "라운드 후 잘된 것 1개, 고칠 것 1개 기록"]$sd$::jsonb,$sd$["작전을 세웠지만 치다 보면 잊어버림 → 라운드 중간(90초)에 작전을 한 번 되뇌기", "유형과 상관없이 같은 콤비만 반복 → 유형마다 시작 기술을 다르게 정해두기"]$sd$::jsonb,31,311,$sd$/assets/training/game-plan-shadow.png$sd$),
($sd$풋워크$sd$,$sd$링 커팅 풋워크$sd$,$sd$움직이는 상대의 길을 미리 막고 링 구석으로 공간을 줄여 가는 발놀림이에요.$sd$,$sd$상대를 쫓아가면 계속 도망가지만, 길을 막으면 멈추게 됩니다. 링 중앙에서 대각선 스텝으로 상대의 이동 방향을 미리 차단하며, 로프와 코너 쪽으로 공간을 조금씩 줄여 가는 풋워크를 연습합니다. 바닥에 테이프로 링 라인을 표시하고 코치나 파트너가 움직이는 역할을 맡아 주면 좋습니다. 직접 닿지 않고 위치만으로 상대를 통제하는, 거리 지배의 핵심 기술입니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$고급$sd$,$sd$["따라가지 말고 지름길로 먼저 서기", "어깨는 항상 상대 중심을 향하게", "반 발씩 공간을 줄이고 한 번에 크게 쫓지 않기", "몰았으면 잽으로 문 잠그기(터치만)"]$sd$::jsonb,$sd$["상대 뒤를 그대로 쫓아감 → 상대가 가려는 방향의 앞 지점으로 대각선 이동", "몰아넣고 급해져 달려듦 → 거리 유지한 채 가드 올리고 천천히 압박"]$sd$::jsonb,31,312,$sd$/assets/training/ring-cutting-footwork.png$sd$),
($sd$회복$sd$,$sd$마스터 리커버리 루틴$sd$,$sd$훈련 뒤 10분, 호흡과 스트레칭으로 몸을 부드럽게 되돌리는 회복 루틴이에요.$sd$,$sd$많이 훈련하는 사람일수록 회복도 훈련처럼 다룹니다. 훈련 직후 10분 동안 호흡 정리(2분), 손목과 어깨 돌리기(2분), 고관절과 햄스트링 스트레칭(4분), 마무리 이완(2분)의 순서로 진행합니다. 스트레칭은 반동 없이 한 자세를 20~30초씩 부드럽게 유지하고, 아픔이 아니라 시원한 당김이 느껴지는 범위까지만 갑니다. 이 루틴을 습관으로 만들면 다음 훈련을 더 좋은 몸 상태로 시작할 수 있습니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$고급$sd$,$sd$["호흡은 들숨보다 날숨을 길게", "반동 금지, 지그시 20초 이상 유지", "많이 쓴 부위(어깨, 손목)부터 먼저", "물 한 컵 마시며 마무리"]$sd$::jsonb,$sd$["아픈 지점까지 당겨 늘림 → 시원한 정도에서 멈추고 호흡으로 천천히 이완", "훈련 끝나자마자 바로 이동 → 최소 호흡 2분과 어깨·손목 풀기 2분만이라도 하기"]$sd$::jsonb,31,313,$sd$/assets/training/master-recovery-routine.png$sd$),
($sd$콤비네이션$sd$,$sd$콤비 프리스타일 설계 랩$sd$,$sd$정해진 콤비를 따라 하지 않고, 나만의 콤비를 직접 만들어 완성하는 훈련이에요.$sd$,$sd$블랙 리그부터는 콤비를 '외우는 사람'에서 '만드는 사람'이 됩니다. 위-아래, 좌-우, 직선-곡선이 골고루 섞이도록 원칙을 지켜 4~6타 콤비를 직접 설계하고, 각 펀치가 왜 그 순서인지 한 줄씩 이유를 적어 봅니다. 설계한 콤비를 섀도로 다듬은 뒤 샌드백에서 리듬을 붙여 완성하고, 가장 잘 되는 두 개를 '나의 시그니처 콤비'로 정리합니다. 코치에게 설계 이유를 설명해 보면 이해가 두 배로 깊어집니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$고급$sd$,$sd$["위를 친 다음은 아래, 아래 다음은 위", "마지막 타는 가드 복귀가 쉬운 펀치로", "타수보다 연결의 이유가 먼저", "시그니처 콤비에는 이름을 붙여 기억"]$sd$::jsonb,$sd$["멋있어 보이는 긴 콤비만 나열 → 4타로 줄이고 각 타의 목적을 말로 설명하기", "설계만 하고 몸으로 안 굳힘 → 콤비 하나당 섀도 20회, 샌드백 20회 반복"]$sd$::jsonb,32,324,$sd$/assets/training/freestyle-combo-design.png$sd$),
($sd$콤비네이션$sd$,$sd$페인트 체인 콤비$sd$,$sd$치는 척 동작으로 상대 반응을 끌어낸 뒤 진짜 공격을 연결하는 기술이에요.$sd$,$sd$페인트는 어깨, 시선, 발끝으로 '치는 척'을 보여 상대의 가드와 체중을 먼저 움직이게 만드는 기술입니다. 잽 페인트 후 스트레이트, 보디 페인트 후 위쪽 훅처럼 '보여주기 다음 진짜'의 짝을 정해 섀도와 샌드백에서 연결합니다. 페인트는 진짜처럼 보이되 균형이 무너지지 않도록 절반 깊이로만 들어갔다 나옵니다. 미트를 잡아 주는 파트너가 페인트에 반응해 주면 효과가 훨씬 커집니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$고급$sd$,$sd$["페인트도 눈빛은 진짜처럼", "반 박자 멈췄다가 진짜를 출발", "페인트 깊이는 절반, 균형은 100%", "상대 가드가 움직인 곳의 반대쪽을 치기"]$sd$::jsonb,$sd$["페인트가 너무 커서 균형이 무너짐 → 어깨와 앞발만 살짝, 몸통은 제자리", "페인트와 진짜 사이가 길어 들킴 → '척-탁' 한 박자 안에 연결하기"]$sd$::jsonb,32,325,$sd$/assets/training/feint-chain-combo.png$sd$),
($sd$샌드백$sd$,$sd$리듬 변속 샌드백$sd$,$sd$같은 콤비를 빠르게, 느리게, 반 박자 당겨서 리듬을 바꿔 가며 치는 샌드백 훈련이에요.$sd$,$sd$일정한 리듬은 상대가 가장 읽기 쉬운 리듬입니다. 이 훈련에서는 한 라운드 안에 '느리게 10초, 빠르게 10초, 반 박자 당겨 치기 10초'처럼 템포 구간을 정해 두고 같은 콤비를 리듬만 바꿔 반복합니다. 느린 구간에는 폼과 호흡을 점검하고, 빠른 구간에도 폼이 흐트러지지 않는지 확인합니다. 리듬을 내 마음대로 바꿀 수 있게 되면 타이밍 카운터의 문이 열립니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$고급$sd$,$sd$["느릴 때는 발-허리-주먹 순서를 느끼며", "빠를 때도 가드 복귀는 그대로", "반 박자 당길 때는 스텝인과 동시에 출발", "10초마다 스스로 구령으로 전환"]$sd$::jsonb,$sd$["빨라지면 팔로만 침 → 속도를 한 단계 낮추고 허리 회전부터 다시", "리듬 변화가 몸에 안 보임 → 메트로놈이나 음악 비트에 맞춰 구간 구분하기"]$sd$::jsonb,32,326,$sd$/assets/training/rhythm-shift-bag.png$sd$),
($sd$풋워크$sd$,$sd$거리 지배 미러 스텝$sd$,$sd$파트너와 마주 서서 정한 거리를 그대로 지키며 따라다니는 발놀림 게임이에요.$sd$,$sd$고수는 주먹이 아니라 거리로 흐름을 지배합니다. 파트너와 두 팔 길이의 거리를 정해 두고, 한 사람이 자유롭게 움직이면 다른 사람이 그 거리를 그대로 유지하며 따라다닙니다. 접촉 없이 스텝만 사용하고, 30초마다 리드 역할을 바꿉니다. 익숙해지면 '먼 거리-중간 거리' 두 구역을 오가며 내가 원하는 거리에만 머무는 연습으로 발전시킵니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$고급$sd$,$sd$["시선은 상대 가슴 중앙에 고정", "거리가 좁혀지면 뒤가 아니라 옆으로 돌기", "발이 교차하지 않게 바운스 유지", "리드일 때는 급출발과 급정지로 흔들어 보기"]$sd$::jsonb,$sd$["뒤로만 빠져 구석에 갇힘 → 두 걸음 물러났다면 세 걸음째는 사이드로", "거리에 집중하다 가드가 내려감 → 가드 위치를 유지한 채 스텝하기"]$sd$::jsonb,33,337,$sd$/assets/training/distance-mirror-step.png$sd$),
($sd$미트$sd$,$sd$하이레벨 콜아웃 미트$sd$,$sd$코치가 외치는 번호와 신호에 즉시 반응해 콤비와 수비를 바꾸는 고난도 미트예요.$sd$,$sd$정해진 순서를 치는 미트를 졸업하고, 이제는 귀와 눈으로 반응합니다. 코치가 라운드 중에 번호 콜(예: '1-2-3!'), 수비 신호(미트를 살짝 내밀면 슬립), 방향 신호를 즉흥으로 외치면 반 박자 안에 그대로 실행합니다. 콜과 콜 사이에는 바운스와 잽으로 리듬을 유지하고, 낯선 신호가 나와도 멈추지 않고 가드부터 챙깁니다. 판단 속도와 기술이 한 번에 단련되는 블랙 리그 대표 미트 훈련입니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$고급$sd$,$sd$["신호를 예상하지 말고 들리는 대로", "콜과 콜 사이에도 발은 계속 살아 있게", "틀려도 멈추지 말고 가드 복귀 먼저", "마지막 타는 항상 정확하게 치고 접고 나오기"]$sd$::jsonb,$sd$["신호를 기다리며 발이 멈춤 → 콜 사이에 잽 1회, 스텝 1회 규칙 만들기", "빨리 치려다 헛스윙 → 정확도 우선, 속도는 정타율 80% 이후에 올리기"]$sd$::jsonb,33,338,$sd$/assets/training/callout-reaction-mitts.png$sd$),
($sd$스파링준비$sd$,$sd$기술 스파링 라운드 플랜 운영$sd$,$sd$라운드마다 주제를 정해 놓고, 가벼운 터치로 계획을 실행하는 기술 스파링이에요.$sd$,$sd$헤드기어, 마우스피스, 16온스 글러브를 착용하고 힘은 미리 약속한 가벼운 터치 강도로만 진행합니다. 시작 전에 파트너와 함께 라운드 주제를 정합니다 — 예를 들어 1라운드는 잽과 거리, 2라운드는 수비와 카운터, 3라운드는 자유 기술입니다. 라운드가 끝나면 30초 동안 서로 잘된 점을 하나씩 말해 주고 다음 주제로 넘어갑니다. 이기는 연습이 아니라 계획을 지키는 연습이며, 강도가 올라가면 코치가 즉시 중단합니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$고급$sd$,$sd$["시작 전 주제와 터치 강도를 소리 내어 약속", "주제에 없는 기술은 아껴 두기", "맞아도 급해지지 말고 플랜으로 복귀", "라운드 후 파트너 칭찬 한 가지씩"]$sd$::jsonb,$sd$["집중하다 보면 터치가 강해짐 → 즉시 멈추고 강도를 다시 약속한 뒤 재개", "플랜을 잊고 자유 공방이 됨 → 코치가 주제 단어를 외쳐 상기시키기(예: '잽 라운드!')"]$sd$::jsonb,33,339,$sd$/assets/training/technical-sparring-plan.png$sd$),
($sd$카운터$sd$,$sd$카운터 체인 드릴$sd$,$sd$카운터를 한 번으로 끝내지 않고, 상대의 되받기까지 다시 받아치는 2연속 카운터예요.$sd$,$sd$블랙 리그의 카운터는 한 수 더 깊게 봅니다. 파트너와 약속된 느린 템포로, 상대의 잽에 슬립 후 스트레이트로 받아치고(1차 카운터), 이어지는 상대의 되받기까지 미리 준비한 수비와 반격으로 한 번 더 받아칩니다(2차 카운터). '공격-카운터-재반격-재카운터'의 네 박자를 한 세트로 정해 천천히 완성한 뒤 조금씩 템포를 올립니다. 접촉은 가드와 어깨에 닿는 터치 수준으로만 유지합니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$고급$sd$,$sd$["1차 카운터 직후가 가장 위험한 순간, 바로 수비 자세", "머리 위치는 카운터마다 다른 곳으로", "네 박자를 입으로 세며 진행", "템포는 성공률 80% 이후에만 올리기"]$sd$::jsonb,$sd$["1차 카운터 후 그 자리에 서 있음 → 치는 즉시 슬립 또는 반 발 이동을 붙이기", "빨리 하려다 순서가 엉킴 → 다시 느린 템포로 돌아가 네 박자 복원하기"]$sd$::jsonb,34,350,$sd$/assets/training/counter-chain-drill.png$sd$),
($sd$카운터$sd$,$sd$브레이크 리듬 카운터$sd$,$sd$일부러 리듬을 흔들어 상대의 공격을 끌어내고, 그 순간을 받아치는 타이밍 훈련이에요.$sd$,$sd$상대가 치고 싶어지는 순간을 내가 만들어 주면, 카운터는 기다림이 아니라 설계가 됩니다. 바운스 리듬을 일정하게 보여주다가 일부러 잠깐 멈추거나 가드를 반 뼘만 열어, 미트 파트너의 느린 잽 신호를 끌어낸 뒤 준비해 둔 슬립과 카운터로 받아칩니다. 파트너는 열림이 보일 때만 천천히 신호를 보내 주고, 강도는 터치 수준을 유지합니다. '보여주기-끌어내기-받아치기'의 흐름을 몸에 새기는 훈련입니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$고급$sd$,$sd$["리듬은 보여주는 것, 마음은 준비 상태", "멈춤은 1초 이내로 짧게", "끌어낸 공격은 눈으로 끝까지 보고 피하기", "카운터 후 즉시 평소 리듬으로 복귀"]$sd$::jsonb,$sd$["미끼를 던져 놓고 정말 방심함 → 가드를 여는 폭은 반 뼘, 손은 언제든 복귀 가능하게", "기다리는 시간이 길어 발이 굳음 → 미끼는 한 라운드에 3~4회만, 나머지는 평소 리듬"]$sd$::jsonb,34,351,$sd$/assets/training/broken-rhythm-counter.png$sd$),
($sd$코칭$sd$,$sd$폼 관찰·교정 체크$sd$,$sd$후배의 잽과 가드를 체크리스트로 관찰하고, 한 번에 하나씩 고쳐 주는 코치 역할 훈련이에요.$sd$,$sd$가르쳐 보면 내 기술이 완성됩니다. 코치의 안내에 따라 후배 한 명의 잽 10회를 옆과 앞에서 관찰하고, 세 가지 체크포인트(스탠스 폭, 턱과 가드, 주먹 복귀)에 O/X를 기록합니다. 고칠 점이 여러 개 보여도 가장 기본이 되는 한 가지만 골라 '이렇게 해 보자'라는 긍정의 말로 전달합니다. 교정 후 다시 10회를 관찰해 변화를 확인하고, 꼭 칭찬으로 마무리합니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$고급$sd$,$sd$["관찰은 옆에서 5회, 앞에서 5회", "지적은 한 번에 딱 하나만", "말보다 시범을 먼저 보여주기", "끝날 때는 좋아진 점을 콕 집어 칭찬"]$sd$::jsonb,$sd$["보이는 문제를 전부 말해 줌 → 체크리스트에 적기만 하고 전달은 1순위 하나만", "'그거 틀렸어'라고 말함 → '가드를 턱에 붙이면 더 좋아져요'처럼 방향으로 말하기"]$sd$::jsonb,35,362,$sd$/assets/training/form-check-coaching.png$sd$),
($sd$코칭$sd$,$sd$티칭 시범 3단 스피드$sd$,$sd$기술 하나를 느리게, 보통, 제 속도의 세 단계로 나눠 설명하며 보여주는 시범 훈련이에요.$sd$,$sd$시범은 최고의 복습입니다. 화이트~블루 리그 기술 중 하나를 골라, 먼저 느린 속도로 동작을 쪼개어 설명하고, 보통 속도로 흐름을 보여준 뒤, 마지막에 제 속도로 완성 동작을 보여줍니다. 보는 사람이 잘 볼 수 있도록 정면과 옆면 두 방향에서 시범을 반복하고, 각 단계마다 핵심 포인트를 한 문장으로 말합니다. 말과 몸이 같은 것을 설명할 수 있을 때 진짜 이해했다는 뜻입니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$고급$sd$,$sd$["느린 시범에서는 순서를, 제 속도에서는 리듬을", "정면 1회, 옆면 1회는 기본", "포인트는 단계마다 한 문장으로", "보는 사람 눈높이에 맞는 쉬운 단어 쓰기"]$sd$::jsonb,$sd$["제 속도로만 멋지게 보여줌 → 느린 단계부터, 보는 사람이 따라올 속도로", "설명이 길어져 시범이 묻힘 → 말은 한 문장, 나머지는 몸으로 보여주기"]$sd$::jsonb,35,363,$sd$/assets/training/three-speed-demo.png$sd$),
($sd$코칭$sd$,$sd$후배 미트 잡아주기$sd$,$sd$후배의 원투를 안전하게 받아 주며, 구령으로 리드하는 미트 코치 훈련이에요.$sd$,$sd$미트를 잡아 보면 상대의 타이밍과 버릇이 보이기 시작합니다. 코치의 감독 아래 후배의 잽과 원투를 받아 주는 역할을 맡아, 미트를 후배의 어깨 높이에 미리 두고 펀치가 닿는 순간에만 살짝 마주 밀며 받습니다. 구령은 반 박자 미리, 짧고 크게 외치고 후배의 수준에 맞춰 속도를 조절합니다. 잘 맞았을 때 크게 반응해 주면 후배의 자신감도, 나의 리듬 읽는 눈도 함께 자랍니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$고급$sd$,$sd$["미트는 치기 좋은 위치에 미리 준비", "받는 순간에만 살짝 마주 밀기", "구령은 반 박자 먼저, 짧고 크게", "후배의 속도에 내 속도를 맞추기"]$sd$::jsonb,$sd$["미트를 크게 휘둘러 마중 나감 → 손목만 살짝, 팔은 제자리에서 받기", "내가 편한 높이에 미트를 둠 → 후배의 어깨선 기준으로 높이 조절", "빠른 콤비로 후배를 몰아붙임 → 원투까지만, 성공 경험 위주로 진행"]$sd$::jsonb,36,374,$sd$/assets/training/junior-mitt-holding.png$sd$),
($sd$컨디셔닝$sd$,$sd$챔피언 라운드 인터벌$sd$,$sd$3분 운동과 1분 회복을 반복하며 라운드 체력의 끝을 끌어올리는 훈련이에요.$sd$,$sd$블랙 리그의 라운드 운영은 체력이라는 바닥 위에 서 있습니다. 3분 동안 샌드백 콤비, 스텝, 버피를 정한 순서로 돌리고, 1분은 완전히 멈추지 않는 활동 회복(걷기, 호흡 정리)으로 보내는 세트를 3~5회 반복합니다. 각 라운드의 마지막 30초는 '피니시 존'으로 정해 출력을 한 단계 올려, 지쳤을 때도 움직이는 감각을 만듭니다. 폼이 무너지면 즉시 강도를 낮추는 것이 규칙입니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$고급$sd$,$sd$["회복 1분에도 계속 걷기", "피니시 존 30초는 소리 내어 카운트", "호흡은 코로 들이쉬고 입으로 길게", "폼이 무너지면 속도부터 낮추기"]$sd$::jsonb,$sd$["초반 라운드에 힘을 다 씀 → 1라운드는 70%로 시작해 라운드마다 조금씩 올리기", "회복 1분에 주저앉음 → 걸으면서 어깨 털고 호흡 정리하기"]$sd$::jsonb,36,375,$sd$/assets/training/champion-round-interval.png$sd$),
($sd$코칭$sd$,$sd$코너 서포트 역할 훈련$sd$,$sd$라운드 사이 1분 동안 파트너를 돌보고, 딱 한 가지 조언을 전하는 리더 역할 훈련이에요.$sd$,$sd$링 옆의 1분은 짧지만, 좋은 리더는 그 시간을 선물로 만듭니다. 파트너의 기술 훈련 라운드 사이 휴식 1분 동안 물과 수건을 챙기고, 먼저 호흡을 가라앉히는 말('코로 들이쉬고 길게 내쉬자')을 건넵니다. 이어서 다음 라운드에 쓸 조언을 딱 한 가지만 쉬운 말로 전하고, 마지막 10초에는 자신감을 주는 한마디로 내보냅니다. 라운드 중 관찰, 휴식 중 돌봄, 한 가지 조언 — 이 순서를 지키는 것이 핵심입니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$고급$sd$,$sd$["처음 20초는 말 걸지 말고 호흡부터", "조언은 한 가지, 열 단어 이내로", "라운드 중에는 메모하며 관찰", "내보낼 때는 어깨 두드리며 긍정 한마디"]$sd$::jsonb,$sd$["1분 내내 조언을 쏟아냄 → 적어 둔 것 중 1순위 하나만 말하고 나머지는 다음 기회에", "'왜 그걸 못 해'라고 다그침 → '이번엔 잽부터 가 보자'처럼 다음 행동으로 말하기"]$sd$::jsonb,37,386,$sd$/assets/training/corner-support-role.png$sd$),
($sd$스파링준비$sd$,$sd$마스터 쇼케이스 라운드$sd$,$sd$화이트부터 블랙까지 배운 기술을 3라운드 구성으로 짜서 보여주는 종합 시연이에요.$sd$,$sd$지금까지의 여정을 한 편의 시연으로 완성합니다. 1라운드는 풋워크와 잽 게임, 2라운드는 시그니처 콤비와 페인트, 3라운드는 수비와 카운터 체인으로 주제를 정해, 섀도·샌드백·미트를 조합한 나만의 시연 구성을 직접 짭니다. 코치 앞에서 전체를 리허설하고, 흔들린 구간을 기록해 다음 리허설에서 보완합니다. MASTER 40 최종 점검의 바탕이 되는 훈련이니 구성표를 글로 남겨 두는 것이 좋습니다.$sd$,$sd$$sd$,$sd$$sd$,$sd$고급$sd$,$sd$["라운드마다 주제가 한눈에 보이게", "잘하는 것 80%, 도전 기술 20%로 구성", "실수해도 표정과 리듬은 그대로", "마지막 30초에 가장 자신 있는 장면 배치"]$sd$::jsonb,$sd$["어려운 기술을 몰아넣어 흐름이 끊김 → 성공률 90% 기술 중심으로 재구성", "구성 없이 즉흥으로 채움 → 30초 단위 구성표를 먼저 쓰고 몸으로 옮기기"]$sd$::jsonb,38,397,$sd$/assets/training/master-showcase-round.png$sd$);